DO $$
DECLARE n int; step jsonb;
BEGIN
  SELECT count(*) INTO n FROM agent_definitions WHERE type='css-patch-agent' AND is_active AND COALESCE(is_snapshot,false)=false AND deleted_at IS NULL;
  IF n <> 1 THEN RAISE EXCEPTION '522: expected exactly 1 live css-patch-agent row, found %', n; END IF;
  SELECT default_config #> ARRAY['workflow','steps','complete'] INTO step FROM agent_definitions WHERE type='css-patch-agent' AND is_active AND COALESCE(is_snapshot,false)=false AND deleted_at IS NULL;
  IF step IS NULL THEN RAISE EXCEPTION '522: css-patch-agent has no complete step — re-derive'; END IF;
  IF step->>'action' <> 'complete_workflow' THEN RAISE EXCEPTION '522: complete runs %, not complete_workflow', step->>'action'; END IF;
  IF step->'config' ? 'result_mapping' THEN RAISE EXCEPTION '522: complete ALREADY carries result_mapping (%)', step->'config'->'result_mapping'; END IF;
  IF step->'config'->'output_fields' <> '["css_fix","css_deployed"]'::jsonb THEN RAISE EXCEPTION '522: output_fields is %, want exactly the two-entry list', step->'config'->'output_fields'; END IF;
  IF (SELECT default_config #>> ARRAY['workflow','steps','deploy_css','action'] FROM agent_definitions WHERE type='css-patch-agent' AND is_active AND COALESCE(is_snapshot,false)=false AND deleted_at IS NULL) <> 'git_commit' THEN RAISE EXCEPTION '522: deploy_css no longer runs git_commit'; END IF;
  IF (SELECT default_config #>> ARRAY['workflow','steps','deploy_css','output_field'] FROM agent_definitions WHERE type='css-patch-agent' AND is_active AND COALESCE(is_snapshot,false)=false AND deleted_at IS NULL) <> 'css_deployed' THEN RAISE EXCEPTION '522: deploy_css output_field changed'; END IF;
END $$;
UPDATE agent_definitions SET default_config = jsonb_set(default_config #- '{workflow,steps,complete,config,output_fields}', '{workflow,steps,complete,config,result_mapping}', jsonb_build_object('css_fix','css_fix','css_deployed','css_deployed','commit_sha','css_deployed.response.data.commit_sha'), true), updated_at=NOW() WHERE type='css-patch-agent' AND is_active AND COALESCE(is_snapshot,false)=false AND deleted_at IS NULL;
-- VERIFY (full file): asserts the exact 3-key result_mapping, asserts against a REAL completed orchestration that css_deployed.response.data.commit_sha resolves, RAISE EXCEPTION (not SELECT) throughout per RFC_006/ON_ERROR_STOP.
